import java.util.*;
import java.io.*;

public class Main {
    static int N, Q;
    static ArrayList<Integer>[] adj;
    static int[] parent, depth, size, heavy, head, pos;
    static int[] nodeAtPos;
    static int curPos;
    static int[][] up;
    static final int LOG = 18;
    static int[] segTree;
    static final int INF = Integer.MAX_VALUE;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Integer.parseInt(st.nextToken());
        parent = new int[N + 1];
        parent[1] = 0;
        if (N > 1) {
            st = new StringTokenizer(br.readLine());
            for (int i = 2; i <= N; i++) {
                parent[i] = Integer.parseInt(st.nextToken());
            }
        }
        // Build adjacency
        adj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) adj[i] = new ArrayList<>();
        for (int i = 2; i <= N; i++) {
            adj[parent[i]].add(i);
        }

        // Precompute binary lifting
        up = new int[N + 1][LOG + 1];
        for (int i = 1; i <= N; i++) up[i][0] = parent[i];
        for (int j = 1; j <= LOG; j++) {
            for (int i = 1; i <= N; i++) {
                up[i][j] = up[up[i][j - 1]][j - 1];
            }
        }

        // HLD
        depth = new int[N + 1];
        size = new int[N + 1];
        heavy = new int[N + 1];
        head = new int[N + 1];
        pos = new int[N + 1];
        nodeAtPos = new int[N + 1];
        curPos = 0;

        dfs1(1);
        dfs2(1, 1);

        // Segment tree
        segTree = new int[4 * N];
        Arrays.fill(segTree, INF);

        st = new StringTokenizer(br.readLine());
        Q = Integer.parseInt(st.nextToken());
        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < Q; q++) {
            st = new StringTokenizer(br.readLine());
            int type = Integer.parseInt(st.nextToken());
            if (type == 1) {
                int v = Integer.parseInt(st.nextToken());
                int k = Integer.parseInt(st.nextToken());
                int f = -1;
                if (v != 1) {
                    f = queryHighestMarked(parent[v]);
                }
                int ans;
                if (f == -1) {
                    ans = kthAncestor(v, k);
                } else {
                    if (k == 1) {
                        ans = f;
                    } else {
                        ans = kthAncestor(f, k - 1);
                    }
                }
                sb.append(ans).append('\n');
            } else {
                int v = Integer.parseInt(st.nextToken());
                update(pos[v], pos[v]);
            }
        }
        System.out.print(sb);
    }

    static void dfs1(int u) {
        size[u] = 1;
        int maxSize = 0;
        for (int v : adj[u]) {
            depth[v] = depth[u] + 1;
            dfs1(v);
            size[u] += size[v];
            if (size[v] > maxSize) {
                maxSize = size[v];
                heavy[u] = v;
            }
        }
    }

    static void dfs2(int u, int h) {
        head[u] = h;
        pos[u] = ++curPos;
        nodeAtPos[curPos] = u;
        if (heavy[u] != 0) {
            dfs2(heavy[u], h);
        }
        for (int v : adj[u]) {
            if (v != heavy[u]) {
                dfs2(v, v);
            }
        }
    }

    static int kthAncestor(int u, int k) {
        for (int j = 0; j <= LOG; j++) {
            if ((k & (1 << j)) != 0) {
                u = up[u][j];
            }
        }
        return u;
    }

    static void update(int idx, int val) {
        update(1, 1, N, idx, val);
    }

    static void update(int node, int l, int r, int idx, int val) {
        if (l == r) {
            segTree[node] = val;
            return;
        }
        int mid = (l + r) / 2;
        if (idx <= mid) update(node * 2, l, mid, idx, val);
        else update(node * 2 + 1, mid + 1, r, idx, val);
        segTree[node] = Math.min(segTree[node * 2], segTree[node * 2 + 1]);
    }

    static int query(int L, int R) {
        if (L > R) return INF;
        return query(1, 1, N, L, R);
    }

    static int query(int node, int l, int r, int L, int R) {
        if (L <= l && r <= R) {
            return segTree[node];
        }
        int mid = (l + r) / 2;
        int res = INF;
        if (L <= mid) res = Math.min(res, query(node * 2, l, mid, L, R));
        if (R > mid) res = Math.min(res, query(node * 2 + 1, mid + 1, r, L, R));
        return res;
    }

    static int[][] segs = new int[20][2];

    static int queryHighestMarked(int u) {
        if (u == 0) return -1;
        int segCount = 0;
        int cur = u;
        while (head[cur] != 1) {
            segs[segCount][0] = pos[head[cur]];
            segs[segCount][1] = pos[cur];
            segCount++;
            cur = parent[head[cur]];
        }
        segs[segCount][0] = pos[1];
        segs[segCount][1] = pos[cur];
        segCount++;
        for (int i = segCount - 1; i >= 0; i--) {
            int L = segs[i][0];
            int R = segs[i][1];
            int minPos = query(L, R);
            if (minPos != INF) {
                return nodeAtPos[minPos];
            }
        }
        return -1;
    }
}
```

## 4. RETROSPECTO E VERIFICAÇÃO

- **Validação com os exemplos:** A solução foi testada mentalmente contra todos os quatro exemplos fornecidos e produz as saídas corretas.
- **Casos de borda:** 
  - `v = 1` em consultas do tipo 1 nunca ocorre com `k ≥ 1`, mas mesmo se ocorresse, a lógica com `parent[1] = 0` retornaria `-1` para `f` e usaria o caminho original, o que seria correto (embora não haja superior).
  - Múltiplas reestruturações no mesmo nó são tratadas como atualizações idempotentes na segment tree.
  - A binary lifting está preparada para `k` até `N`, garantindo que o `k`-ésimo ancestral exista.
- **Complexidade:** O uso de HLD e segment tree garante `O(log^2 N)` por consulta, e a binary lifting `O(log N)` por consulta de ancestral original. Para os limites dados, a solução executa confortavelmente dentro do tempo limite.
- **Memória:** Os arrays utilizados ocupam poucos megabytes, bem abaixo de qualquer limite típico (ex.: 256 MB).

A solução é robusta, ótima e atende a todos os requisitos do problema.

